import {on} from 'delegated-events'

// Okta SSWS Token fields behavior
on('details:toggled', '.js-ssws-token', function (event) {
  const detailsContainer = event.currentTarget
  const passwordField = detailsContainer.querySelector<HTMLInputElement>('input[type=password]')!

  if (detailsContainer.classList.contains('open')) {
    passwordField.focus()
  }
})
